"use strict";
const $=id=>document.getElementById(id), state={token:null,method:null,analysis:null,answers:{},reviews:{},result:null};
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const status=t=>$("status").textContent=t;
async function api(path,data){const headers={"Content-Type":"application/json"};if(state.token)headers.Authorization="Bearer "+state.token;const r=await fetch("/api/"+path,{method:data===undefined?"GET":"POST",headers,body:data===undefined?undefined:JSON.stringify(data)});const x=await r.json();if(!r.ok)throw Error(x.error||"Request failed");return x;}
function step(n){for(let i=1;i<=3;i++)$("step"+i).hidden=i!==n;for(const b of document.querySelectorAll("nav [data-step]")){if(Number(b.dataset.step)===n)b.setAttribute("aria-current","step");else b.removeAttribute("aria-current");}if(n===3)renderResults();window.scrollTo(0,0);}
document.querySelectorAll("[data-step]").forEach(b=>b.addEventListener("click",()=>step(Number(b.dataset.step))));
$("loginform").addEventListener("submit",async e=>{e.preventDefault();try{const x=Object.fromEntries(new FormData(e.target));state.token=(await api("login",x)).token;state.method=await api("methodology");$("ai-draft").hidden=!state.method.modelEnabled;state.analysis=await api("analyze");$("login").hidden=true;$("work").hidden=false;e.target.reset();for(const d of Object.keys(state.method.weights))$("dimension").append(el("option",d));renderFiles();renderQuestions();step(1);status("");}catch(err){status(err.message);}});
$("logout").onclick=async()=>{try{await api("logout",{});}finally{location.reload();}};
$("uploadform").addEventListener("submit",async e=>{e.preventDefault();const files=[...$("files").files];const button=e.target.querySelector("button");button.disabled=true;try{for(const file of files){if(file.size>256*1024)throw Error(file.name+" exceeds 256 KB");status("Analysing "+file.name+"…");const bytes=new Uint8Array(await file.arrayBuffer());let bin="";for(const b of bytes)bin+=String.fromCharCode(b);await api("upload",{filename:file.name,content:btoa(bin),synthetic:$("fictional").checked});}state.analysis=await api("analyze");state.reviews={};state.result=null;renderFiles();e.target.reset();status("Evidence mapped. Continue to interviews.");}catch(err){state.analysis=await api("analyze");state.reviews={};state.result=null;renderFiles();status(err.message);}finally{button.disabled=false;}});
function renderFiles(){const a=state.analysis;$("filecount").textContent=a.files.length+" files";$("filelist").replaceChildren();for(const f of a.files){const d=el("div",undefined,"file");d.append(el("strong",f.name),el("p",f.format.toUpperCase()+" · "+f.segments+" extracted passages · format only; not malware scanned","muted"));$("filelist").append(d);}const mapped=a.criteria.filter(c=>c.sources.length).length;$("coverage").replaceChildren(el("p",mapped+" of 28 criteria have candidate evidence. "+a.criteria.filter(c=>c.suggested!==null).length+" tentative anchor suggestions.","row"));}
$("dimension").onchange=renderQuestions;
function renderQuestions(){const d=$("dimension").value;$("questions").replaceChildren();for(const c of state.method.criteria.filter(c=>c.dimension===d)){const l=el("label",c.question);const t=el("textarea");t.placeholder="Stakeholder response or Unknown";t.value=state.answers[c.id]||"";t.maxLength=4000;t.oninput=()=>{state.answers[c.id]=t.value;delete state.reviews[c.id];state.result=null;};l.append(t);$("questions").append(l);}}
function showScore(){const card=$("scorecard");card.replaceChildren();const r=state.result;const left=el("div");left.append(el("p","WEIGHTED TCI™ DRAFT"),el("strong",r&&r.draftScore!==null?r.draftScore.toFixed(2)+" / 5":"— / 5"),el("p",r?r.reviewed+" / 28 criteria reviewed":"Complete review to calculate"),el("p",r?.unreviewedModelScore!=null?"Unreviewed AI candidate: "+r.unreviewedModelScore.toFixed(2)+" / 5":r?.proposedCriteria?"AI candidates: "+r.proposedCriteria+" / 28":""));const right=el("div");for(const [d,w] of Object.entries(state.method.weights)){const line=el("div",undefined,"dim");line.append(el("span",d+" · "+w+"%"),el("b",r?.dimensions[d].score!=null?r.dimensions[d].score.toFixed(2):r?.dimensions[d].proposal!=null?r.dimensions[d].proposal.toFixed(2)+" candidate":"—"));right.append(line);}card.append(left,right);}
function renderResults(){showScore();const results=$("results");results.replaceChildren();for(const [d,w] of Object.entries(state.method.weights)){const group=state.method.criteria.filter(c=>c.dimension===d);const box=el("details");box.append(el("summary",d+" · "+w+"% weighting"));for(const c of group){const a=state.analysis.criteria.find(x=>x.id===c.id), row=el("div",undefined,"criterion");row.append(el("h3",c.criterion+" · "+c.criterionWeight+"% of dimension"),el("p",c.minimum),el("p",state.answers[c.id]?"Interview: "+state.answers[c.id]:"Interview not entered","muted"));if(!a.sources.length){row.append(el("p","No candidate evidence — score withheld","muted"));box.append(row);continue;}const review=state.reviews[c.id]||(state.reviews[c.id]={score:a.suggested,confirmed:false,conflict:true,operating:false,rationale:""});if(review.model)row.append(el("p","AI candidate · "+review.model+" · inspect cited passages "+review.sourceIds.join(", "),"muted"));row.append(el("p",a.suggested===null?"Anchor requires judgement":"Lexical candidate: "+a.suggested+" / 5 — verify meaning, not just wording","muted"));const sources=el("details");sources.append(el("summary",a.sources.length+" candidate evidence passages"));for(const [i,s] of a.sources.entries()){const q=el("div",undefined,"citation");q.append(el("small","Passage "+(i+1)+" · "+s.file+" · "+s.locator),el("p",s.quote),el("small","SHA-256 "+s.digest));sources.append(q);}row.append(sources);const label=el("label","Performance anchor");const select=el("select");const blank=el("option","Withhold / not assessed");blank.value="";select.append(blank);for(const anchor of c.anchors){const opt=el("option",anchor.score+" — "+anchor.label+" · "+anchor.description);opt.value=anchor.score;select.append(opt);}select.value=review.score??"";select.onchange=()=>{review.score=select.value?Number(select.value):null;review.confirmed=false;row.querySelector('input[type="checkbox"]').checked=false;state.result=null;showScore();};label.append(select);row.append(label);const reason=el("label","Rationale");const t=el("textarea");t.maxLength=2000;t.value=review.rationale;t.oninput=()=>{review.rationale=t.value;state.result=null;showScore();};reason.append(t);row.append(reason);for(const [key,txt,invert] of [["confirmed","I reviewed exact evidence and interview context",false],["conflict","No material unresolved contradiction",true],["operating","Sustained operating evidence (required for 4–5)",false]]){const l=el("label",undefined,"check");const input=el("input");input.type="checkbox";input.checked=invert?!review[key]:review[key];input.onchange=()=>{review[key]=invert?!input.checked:input.checked;state.result=null;showScore();};l.append(input,el("span",txt));row.append(l);}box.append(row);}results.append(box);}}
$("calculate").onclick=async()=>{try{state.result=await api("calculate",{rows:state.reviews,interviews:state.answers});showScore();status(state.result.draftScore===null?"Draft withheld until all 28 criteria have evidence, interview context and reviewer confirmation.":"Draft weighted score calculated. Independent operational acceptance remains required.");$("scorecard").scrollIntoView({block:"center"});}catch(e){status(e.message);}};

$("ai-draft").onclick=async()=>{const b=$("ai-draft");b.disabled=true;state.result=null;try{let count=0;for(const d of Object.keys(state.method.weights)){status("Generating draft anchors: "+d+"…");const r=await api("propose",{dimension:d,interviews:state.answers});for(const [q,c] of Object.entries(r.candidates)){state.reviews[q]={score:c.score,rationale:c.rationale,sourceIds:c.sourceIds,model:r.model,confirmed:false,conflict:true,operating:false};if(c.score!==null)count++;}}$("ai-note").textContent=count+" AI draft anchors generated. Verify evidence and resolve exceptions; independent approval remains required.";state.result=await api("calculate",{rows:state.reviews,interviews:state.answers});renderResults();status("Draft generated. Scores are provisional pending review.");}catch(e){renderResults();status("Draft incomplete: "+e.message);}finally{b.disabled=false;}};
